INSERT INTO _nft_ordinals_depth_wave_c_0100 (slug, canonical_profile) VALUES ('funko-digital-pop', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:funko-digital-pop","type":"nft_collection","slug":"funko-digital-pop","name":"Funko Digital Pop!","aliases":[]},"classification":{"subtype":"licensed phygital collectible program","tags":["wax","licensed_ip","mystery_packs","physical_redemption","centralized_platform","ceased"],"chains":["WAX"],"jurisdictions":["United States"]},"status":{"operating_state":"operator_program_ceased_2026_assets_may_persist_elsewhere","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:status"]},"outcome":{"label":"failed_operator_program_with_exportable_artifacts_and_outstanding_fulfillment","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:funko-digital-pop:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Funko Digital Pop was a series of licensed digital trading-card drops on the WAX blockchain, sold through the Droppp platform from 2021 to 2026. Buyers opened randomized packs, collected rarity tiers and traded items. Selected rare cards or completed “Royalty Sets” generated time-limited tokens redeemable for physical Funko Pop figures. A Digital Pop was not company stock or a permanent promise of future drops, and most cards carried no physical redemption right.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:what_it_is:1","claim:funko-digital-pop:section:what_it_is:2","claim:funko-digital-pop:section:what_it_is:3"]},"what_happened":{"body":"Funko launched Digital Pop in 2021 and repeatedly paired well-known entertainment licenses with scarce physical figures. On April 30, 2026, Funko announced that no new collections would be released and that Droppp would close on May 31. Users had to open packs and move collectibles and USDC before the deadline. Funko said it would refund Droppp credits and finish outstanding physical orders, while unexported access, pack opening, marketplace service and Discord support ended.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:what_happened:1","claim:funko-digital-pop:section:what_happened:2","claim:funko-digital-pop:section:what_happened:3"]},"why_this_outcome":{"body":"The product’s strongest hook was also its central weakness. Licensed characters and exclusive physical figures gave collectors a reason to buy beyond a digital image, but pack opening, custody, trading, redemption tracking and fulfillment all ran through Droppp and Funko. WAX could preserve exported tokens, yet it could not preserve those operator services. The shutdown is verified; Funko did not publish program revenue, costs, user retention or a detailed reason for ending it, so poor economics should not be presented as proven.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:why_this_outcome:1","claim:funko-digital-pop:section:why_this_outcome:2","claim:funko-digital-pop:section:why_this_outcome:3"]},"strategic_choices":{"body":"Funko chose recurring licensed drops rather than one permanent collection, mystery packs rather than direct selection and physical redemption rather than digital-only utility. It also used a managed Droppp wallet and marketplace to hide much of the blockchain complexity from mainstream collectors. Those choices made the product familiar to trading-card and Funko buyers, but required continuous licensing, inventory design, shipping and platform operations. The late export window reduced damage without making the product self-sustaining.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:strategic_choices:1","claim:funko-digital-pop:section:strategic_choices:2","claim:funko-digital-pop:section:strategic_choices:3"]},"operating_model":{"body":"Collectors bought packs, received WAX-based items in Droppp and could trade through its marketplace. On a snapshot date after a drop, the current owner of an eligible card received a redemption token, which then had to be redeemed for a physical figure within the stated window. Funko and its partners controlled licenses, pack inventory, eligibility and physical fulfillment. WAX handled token custody after export, but an external wallet could not reopen a sealed pack or recreate Funko’s redemption database after closure.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:operating_model:1","claim:funko-digital-pop:section:operating_model:2","claim:funko-digital-pop:section:operating_model:3"]},"token_and_value_capture":{"body":"Funko captured primary pack revenue and used scarce physical figures to drive demand; Droppp could also monetize marketplace activity under its terms. Holders captured value only through collectible enjoyment, an eligible physical redemption or resale to another buyer. A digital item’s WAX persistence did not guarantee a buyer, royalty payment, shipping claim or future utility. Current program-level sales, margins, licensing expense, marketplace take rate and final redemption completion are not disclosed in the reviewed sources.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:token_and_value_capture:1","claim:funko-digital-pop:section:token_and_value_capture:2","claim:funko-digital-pop:section:token_and_value_capture:3"]},"counterfactual":{"body":"A self-custody-first design with open pack and redemption standards could have preserved more functions when Droppp closed. A longer read-only period could also have reduced deadline risk. Neither option removes the need for a licensed company to manufacture and ship the physical figures, and continued infrastructure carries real cost. The available record does not show that decentralizing custody would have fixed demand or economics; it would mainly have reduced the number of utilities lost at one shutdown date.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:counterfactual:1","claim:funko-digital-pop:section:counterfactual:2","claim:funko-digital-pop:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The remaining risks are practical, not just market-price risk. Some users may have missed the export or pack-opening deadlines; physical shipments may still be delayed or disputed; metadata and trading depend on third-party WAX services; and licensed imagery does not automatically grant broad commercial rights. Unknowns include final user counts, unexported assets, unopened inventory burned, outstanding redemptions, refunds, program losses and whether Funko will offer a replacement digital product under different terms.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:risks_and_unknowns:1","claim:funko-digital-pop:section:risks_and_unknowns:2","claim:funko-digital-pop:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Digital Pop began in 2021 as a bridge between Funko’s licensed physical collectibles and blockchain trading. Repeated drops extended the line for almost five years, but the program entered terminal wind-down when new releases stopped and Funko announced Droppp’s closure in April 2026. The service ended on May 31. The correct lifecycle call is dead at the operator-product layer with residual artifacts and fulfillment obligations—not that every WAX token vanished, and not that Funko itself ceased operating.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:lifecycle:1","claim:funko-digital-pop:section:lifecycle:2","claim:funko-digital-pop:section:lifecycle:3"]},"outlook_and_watch":{"body":"The terminal status will not change unless Funko launches a clearly documented successor; transferring old tokens on WAX would not revive Digital Pop. Watch completion of outstanding physical orders and refunds, availability of metadata in third-party wallets, any formal rights update and any new Funko digital-collectible strategy. The most important postmortem signal is how many users successfully recovered assets and claims. Funko has not published that reconciliation, so holder recovery remains incomplete as a research question.","as_of":"2026-08-03","claim_ids":["claim:funko-digital-pop:section:outlook_and_watch:1","claim:funko-digital-pop:section:outlook_and_watch:2","claim:funko-digital-pop:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:funko-digital-pop:launch","type":"product_launch","date":"2021-01-01","date_precision":"year","description":"Funko launched the Digital Pop program during 2021.","claim_ids":["claim:funko-digital-pop:event:launch"]},{"id":"event:funko-digital-pop:sunset-announcement","type":"shutdown_announcement","date":"2026-04-30","date_precision":"day","description":"Funko announced that Digital Pop releases had ended and Droppp would close.","claim_ids":["claim:funko-digital-pop:event:sunset-announcement"]},{"id":"event:funko-digital-pop:shutdown","type":"service_shutdown","date":"2026-05-31","date_precision":"day","description":"Droppp accounts, wallets, pack opening and community services ended.","claim_ids":["claim:funko-digital-pop:event:shutdown"]}],"sources":[{"id":"source:funko-digital-pop:mechanics","title":"Funko Digital Pop program mechanics","url":"https://funko.com/digital-pop.html","publisher":"Funko","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://funko.com/digital-pop.html","content_hash":null,"independence_group":"funko","access_method":"direct_http","direct_http_status":200},{"id":"source:funko-digital-pop:sunset","title":"Digital Pop update: Droppp program sunsets May 31, 2026","url":"https://funko.com/funko-blog-home/funko-digital-pop-update.html","publisher":"Funko","published_at":"2026-04-30","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://funko.com/funko-blog-home/funko-digital-pop-update.html","content_hash":null,"independence_group":"funko","access_method":"direct_http","direct_http_status":200},{"id":"source:funko-digital-pop:independent","title":"Funko''s NFT era ends","url":"https://www.nerdbeak.com/news/funko-droppp-digital-pop-shutdown-may-2026","publisher":"Nerdbeak","published_at":"2026-05-29","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"C","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://www.nerdbeak.com/news/funko-droppp-digital-pop-shutdown-may-2026","content_hash":null,"independence_group":"nerdbeak","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:funko-digital-pop:status","field_path":"status.operating_state","assertion":"Funko disabled Droppp accounts, wallets, pack opening and community services on May 31, 2026 after ending new Digital Pop releases.","value":"operator_program_ceased_2026_assets_may_persist_elsewhere","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Dated operator shutdown notice corroborated by independent coverage.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:outcome","field_path":"outcome.label","assertion":"The Digital Pop product failed as a continuing operator program even though timely exported WAX collectibles can remain in third-party wallets.","value":"failed_operator_program_with_exportable_artifacts_and_outstanding_fulfillment","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:funko-digital-pop:mechanics","source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Original product mechanics, explicit terminal event and independent shutdown review.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or a claim of holder profitability.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Funko sold licensed Digital Pop collectibles through randomized packs and a secondary marketplace.","value":"Funko sold licensed Digital Pop collectibles through randomized packs and a secondary marketplace.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:mechanics"],"evidence_locator":"How it works and complete your collection sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Only qualifying rarities or completed sets generated redemption tokens for physical figures.","value":"Only qualifying rarities or completed sets generated redemption tokens for physical figures.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:mechanics"],"evidence_locator":"Physical-redemption explanation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"The reviewed program pages state no equity, revenue-share or permanent future-release right for holders.","value":"The reviewed program pages state no equity, revenue-share or permanent future-release right for holders.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:funko-digital-pop:mechanics","source:funko-digital-pop:sunset"],"evidence_locator":"Product proposition and shutdown notice.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Funko states that Digital Pop launched in 2021.","value":"Funko states that Digital Pop launched in 2021.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Opening paragraphs of the sunset notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"Droppp accounts and wallets were disabled on May 31, 2026.","value":"Droppp accounts and wallets were disabled on May 31, 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Shutdown deadline and independent review.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"Funko committed to refund credits and fulfill outstanding physical redemption orders.","value":"Funko committed to refund credits and fulfill outstanding physical redemption orders.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Credit and physical-order FAQ sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body#1","assertion":"The physical-figure hook depended on Funko eligibility and fulfillment rather than the token alone.","value":"The physical-figure hook depended on Funko eligibility and fulfillment rather than the token alone.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:funko-digital-pop:mechanics","source:funko-digital-pop:sunset"],"evidence_locator":"Redemption mechanics and outstanding-order commitment.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body#2","assertion":"Droppp concentrated wallet, marketplace, pack-opening and community functions in one operator surface.","value":"Droppp concentrated wallet, marketplace, pack-opening and community functions in one operator surface.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:funko-digital-pop:mechanics","source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Program workflow and shutdown consequences.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"Funko did not disclose a quantified financial or retention reason for the closure in the reviewed notice.","value":"Funko did not disclose a quantified financial or retention reason for the closure in the reviewed notice.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Full shutdown notice.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"Digital Pop used recurring licensed drops and randomized packs.","value":"Digital Pop used recurring licensed drops and randomized packs.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:mechanics"],"evidence_locator":"Drop and pack workflow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"The program used a managed account, wallet and marketplace experience through Droppp.","value":"The program used a managed account, wallet and marketplace experience through Droppp.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:mechanics","source:funko-digital-pop:sunset"],"evidence_locator":"Account workflow and shutdown instructions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"Funko allowed WAX exports during shutdown but ended the original service layer.","value":"Funko allowed WAX exports during shutdown but ended the original service layer.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Transfer instructions and terminal deadline.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"The current owner at the applicable snapshot could receive the physical-redemption token.","value":"The current owner at the applicable snapshot could receive the physical-redemption token.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:mechanics"],"evidence_locator":"Redemption-token workflow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"Funko controlled physical-product eligibility and fulfillment.","value":"Funko controlled physical-product eligibility and fulfillment.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:mechanics","source:funko-digital-pop:sunset"],"evidence_locator":"Redemption and outstanding-order sections.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"After closure, exported tokens could persist while Droppp-only functions stopped.","value":"After closure, exported tokens could persist while Droppp-only functions stopped.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Transfer, pack-opening and account-shutdown instructions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"Primary packs and qualifying physical figures were the program’s disclosed commercial products.","value":"Primary packs and qualifying physical figures were the program’s disclosed commercial products.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:mechanics"],"evidence_locator":"Purchase and redemption workflow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"A holder had no disclosed automatic claim on Funko revenue or Droppp fees.","value":"A holder had no disclosed automatic claim on Funko revenue or Droppp fees.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:funko-digital-pop:mechanics","source:funko-digital-pop:sunset"],"evidence_locator":"Reviewed holder proposition.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"Program revenue, margin, licensing cost and final fulfillment counts were not published in the reviewed sources.","value":"Program revenue, margin, licensing cost and final fulfillment counts were not published in the reviewed sources.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Shutdown and independent review.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"The actual design concentrated multiple functions in Droppp.","value":"The actual design concentrated multiple functions in Droppp.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:mechanics","source:funko-digital-pop:sunset"],"evidence_locator":"Product workflow and shutdown effects.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"Funko provided a finite export window rather than permanent Droppp access.","value":"Funko provided a finite export window rather than permanent Droppp access.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"May 31 transfer deadline.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"The effect of a self-custody-first design on demand and profitability is not observed.","value":"The effect of a self-custody-first design on demand and profitability is not observed.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Terminal record contains no controlled comparison.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"Users faced hard deadlines for transfers, pack opening and USDC withdrawal.","value":"Users faced hard deadlines for transfers, pack opening and USDC withdrawal.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Shutdown checklist.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"Funko acknowledged physical-shipping delays while promising completion.","value":"Funko acknowledged physical-shipping delays while promising completion.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Outstanding physical redemption section.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"Final exported-asset, refund, burn and fulfillment totals remain unpublished.","value":"Final exported-asset, refund, burn and fulfillment totals remain unpublished.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Reviewed terminal record.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"The product operated from its 2021 launch until the 2026 sunset.","value":"The product operated from its 2021 launch until the 2026 sunset.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Launch retrospective and closure date.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"New collections, accounts, wallets, pack opening and Discord support ended with the wind-down.","value":"New collections, accounts, wallets, pack opening and Discord support ended with the wind-down.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Program shutdown details.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Exported WAX assets can persist separately from the ceased operator program.","value":"Exported WAX assets can persist separately from the ceased operator program.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Third-party wallet instructions and independent explanation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"Funko said outstanding physical orders and Droppp credits would be honored.","value":"Funko said outstanding physical orders and Droppp credits would be honored.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Fulfillment and refund commitments.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"Third-party WAX support determines residual access after Droppp closure.","value":"Third-party WAX support determines residual access after Droppp closure.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"External-wallet transfer explanation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"No final recovery reconciliation was available in the reviewed sources.","value":"No final recovery reconciliation was available in the reviewed sources.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Post-shutdown record.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:event:launch","field_path":"events[event:funko-digital-pop:launch]","assertion":"Funko launched the Digital Pop program during 2021.","value":"2021-01-01","as_of":"2021-01-01","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Operator launch retrospective.","support_direction":"supports","note":"Source precision: year.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:event:sunset-announcement","field_path":"events[event:funko-digital-pop:sunset-announcement]","assertion":"Funko announced that Digital Pop releases had ended and Droppp would close.","value":"2026-04-30","as_of":"2026-04-30","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset"],"evidence_locator":"Dated operator notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:funko-digital-pop:event:shutdown","field_path":"events[event:funko-digital-pop:shutdown]","assertion":"Droppp accounts, wallets, pack opening and community services ended.","value":"2026-05-31","as_of":"2026-05-31","confidence":"high","kind":"fact","source_ids":["source:funko-digital-pop:sunset","source:funko-digital-pop:independent"],"evidence_locator":"Operator deadline and independent review.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:03:00Z","next_review_at":"2026-08-10T22:03:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["program_revenue_and_costs","final_user_count","export_completion","unopened_pack_burn_total","outstanding_physical_orders","refund_completion","license_rights_after_shutdown"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Funko Inc., the Digital Pop product, Droppp services, WAX tokens, licensed brands and physical-redemption obligations are separate.","metric_boundary":"Historical pack sales, token transfers, marketplace prices and physical fulfillment are different measures and are not combined.","editorial_guardrail":"Do not say every token disappeared when Droppp closed, and do not call residual WAX transferability an operating product.","explicit_unknowns":["program_revenue_and_costs","final_user_count","export_completion","unopened_pack_burn_total","outstanding_physical_orders","refund_completion","license_rights_after_shutdown"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, related-token economics and market price are kept separate.","Terminal status is supported by Funko’s dated notice; the undisclosed business reason is kept unknown."]}}');

INSERT INTO _nft_ordinals_depth_wave_c_0100 (slug, canonical_profile) VALUES ('sorare-cards', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:sorare-cards","type":"nft_collection","slug":"sorare-cards","name":"Sorare Cards","aliases":[]},"classification":{"subtype":"licensed fantasy-sports card platform","tags":["sports","fantasy_game","licensed_ip","seasonal_supply","solana","regulated_game"],"chains":["Solana","Base"],"jurisdictions":["France","United Kingdom","United States"]},"status":{"operating_state":"operating_after_chain_migration_with_financial_and_regulatory_pressure","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:status"]},"outcome":{"label":"surviving_product_with_repeat_gameplay_but_shrinking_economics_and_regulatory_risk","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:sorare-cards:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Sorare is a fantasy-sports platform built around licensed digital player cards. Managers assemble football, baseball or basketball lineups, and real-world player performance determines competition results. Some entry modes use free cards; scarce cards are blockchain collectibles with edition tiers and seasonal identity. The current wallet architecture uses Solana for collectibles and Base for ETH. A card is a game item and transferable collectible, not equity in Sorare or a guaranteed investment return.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:what_it_is:1","claim:sorare-cards:section:what_it_is:2","claim:sorare-cards:section:what_it_is:3"]},"what_happened":{"body":"Sorare launched its football product in 2019, expanded into additional sports and reached a 2021 private valuation associated with hypergrowth expectations. The market then contracted. Independent reporting based on company accounts said revenue fell from €143 million in 2022 to €59 million in 2023 and €43 million in 2024, while cash reserves also declined. Sorare cut burn, adapted products to France’s JONUM framework and migrated collectibles from StarkEx to Solana, showing survival and retrenchment at the same time.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:what_happened:1","claim:sorare-cards:section:what_happened:2","claim:sorare-cards:section:what_happened:3"]},"why_this_outcome":{"body":"Sorare lasted because cards have repeat use in live competitions rather than depending only on profile-picture demand. Sports seasons refresh the game, licenses supply recognizable players and a marketplace lets users change lineups. The same model creates recurring cost and risk: licenses, rewards, compliance and new seasonal inventory must be supported while older cards compete with new supply. Falling revenue shows the 2021 growth story did not persist, while continued competitions and a major chain migration show the product did not simply collapse.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:why_this_outcome:1","claim:sorare-cards:section:why_this_outcome:2","claim:sorare-cards:section:why_this_outcome:3"]},"strategic_choices":{"body":"Sorare chose official league and player licenses, a repeated fantasy-game loop and season-specific scarcity instead of a fixed art collection. It initially used Ethereum scaling infrastructure, then moved collectibles to Solana and ETH settlement to Base. It also adjusted competition formats to fit France’s JONUM regime rather than withdraw entirely. These choices preserved product continuity and mainstream sports identity, but they increased dependence on rights holders, rules in each country, continuing content production and user trust during a complex migration.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:strategic_choices:1","claim:sorare-cards:section:strategic_choices:2","claim:sorare-cards:section:strategic_choices:3"]},"operating_model":{"body":"Sorare creates and sells scarce player-card inventory, operates fantasy competitions and supports transfers between user wallets. Users select lineups; performance data determines scores; eligible rankings can receive cards, cash, merchandise or experiences under competition terms. Payments, withdrawals and transfers remain subject to identity, sanctions and fraud controls. The company therefore combines game publisher, licensed-content buyer, marketplace and wallet interface. Blockchain custody can make a card transferable, but Sorare still controls competition eligibility, scoring and rewards.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:operating_model:1","claim:sorare-cards:section:operating_model:2","claim:sorare-cards:section:operating_model:3"]},"token_and_value_capture":{"body":"Sorare can earn from primary card sales and marketplace or service economics, while paying for licenses, staff, infrastructure and rewards. A card holder can use a card in eligible competitions or sell it, but receives no disclosed share of company profit. Annual issuance supports fresh gameplay and revenue while diluting attention across seasons and scarcity tiers. The reviewed public record does not reconcile current primary sales, marketplace take rate, reward expense, licensing cost, active paying managers or profitability after the migration.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:token_and_value_capture:1","claim:sorare-cards:section:token_and_value_capture:2","claim:sorare-cards:section:token_and_value_capture:3"]},"counterfactual":{"body":"Sorare could have issued fewer seasonal cards, stayed on StarkEx, removed cash-like rewards or operated as a conventional non-transferable fantasy game. Lower issuance might protect older scarcity but reduce new sales and roster coverage. Staying put would avoid migration friction but preserve older infrastructure. Removing transferable value could reduce some regulatory exposure while weakening ownership. No public experiment isolates which design would maximize durable users or profit, so these alternatives should remain scenarios rather than prescriptions.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:counterfactual:1","claim:sorare-cards:section:counterfactual:2","claim:sorare-cards:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The largest risks are declining economics, licensing renewal, regulation, reward affordability, card oversupply, migration or wallet failures and thin markets for older seasons. The UK Gambling Commission’s public notice records a prosecution allegation, not a conviction and not a universal classification of Sorare as gambling. Unknowns include 2025–2026 audited revenue, cash runway, active and retained paying managers, primary-versus-secondary mix, license obligations, take rate, reward cost and how many users or cards were stranded during migration.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:risks_and_unknowns:1","claim:sorare-cards:section:risks_and_unknowns:2","claim:sorare-cards:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Sorare moved from a 2019 football startup to a highly valued multi-sport NFT company, then into a post-boom correction. The 2022–2024 revenue decline and reported cash burn materially weaken the original hypergrowth thesis. Yet current terms, competitions and completed chain migration show an operating product with adaptation capacity. The lifecycle call is surviving and strategically important but financially pressured—not thriving based only on activity, and not dead because card prices fell or regulation became harder.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:lifecycle:1","claim:sorare-cards:section:lifecycle:2","claim:sorare-cards:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Sorare continues as a smaller, more regulated fantasy-sports platform while trying to stabilize costs and card demand. Watch audited revenue and cash, paying-manager retention, league renewals, competition entries, reward delivery, old-card usage, Solana custody incidents and the resolution of UK proceedings. The call improves if active paying cohorts and margins stabilize without aggressive issuance. It worsens if a major license leaves, cash declines faster than costs or legal restrictions remove the rewards that make scarce cards useful.","as_of":"2026-08-03","claim_ids":["claim:sorare-cards:section:outlook_and_watch:1","claim:sorare-cards:section:outlook_and_watch:2","claim:sorare-cards:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:sorare-cards:launch","type":"product_launch","date":"2019-03-01","date_precision":"month","description":"Sorare launched its football fantasy-card beta in March 2019.","claim_ids":["claim:sorare-cards:event:launch"]},{"id":"event:sorare-cards:revenue-peak","type":"financial_peak","date":"2022-12-31","date_precision":"year","description":"Independent reporting identified €143 million of 2022 revenue before a two-year contraction.","claim_ids":["claim:sorare-cards:event:revenue-peak"]},{"id":"event:sorare-cards:current-terms","type":"operating_update","date":"2026-05-07","date_precision":"day","description":"Current terms documented the post-migration Solana and Base wallet structure.","claim_ids":["claim:sorare-cards:event:current-terms"]}],"sources":[{"id":"source:sorare-cards:history","title":"Our next chapter: Sorare beta rollout history","url":"https://medium.com/sorare/our-next-chapter-sorare-raises-a-4m-seed-round-led-by-e-ventures-b8e615bce191","publisher":"Sorare","published_at":"2020-07-16","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://medium.com/sorare/our-next-chapter-sorare-raises-a-4m-seed-round-led-by-e-ventures-b8e615bce191","content_hash":null,"independence_group":"sorare","access_method":"indexed_browser_snapshot","direct_http_status":403},{"id":"source:sorare-cards:terms","title":"Sorare terms and conditions","url":"https://sorare.com/terms-and-conditions","publisher":"Sorare","published_at":"2026-05-07","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://sorare.com/terms-and-conditions","content_hash":null,"independence_group":"sorare","access_method":"direct_http","direct_http_status":200},{"id":"source:sorare-cards:ownership","title":"Security, transparency and ownership","url":"https://sorare.com/help/a/30889391102749/security-transparency-ownership","publisher":"Sorare","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://sorare.com/help/a/30889391102749/security-transparency-ownership","content_hash":null,"independence_group":"sorare","access_method":"direct_http","direct_http_status":200},{"id":"source:sorare-cards:migration","title":"Sorare migration timeline and phases","url":"https://help.sorare.com/hc/en-us/articles/30889042268573-Timeline-Phases","publisher":"Sorare","published_at":"2025-10-08","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://help.sorare.com/hc/en-us/articles/30889042268573-Timeline-Phases","content_hash":null,"independence_group":"sorare","access_method":"indexed_browser_snapshot","direct_http_status":403},{"id":"source:sorare-cards:jonum","title":"JONUM regulation and current Sorare competitions","url":"https://help.sorare.com/hc/en-us/articles/35374770201373-JONUM-Regulation","publisher":"Sorare","published_at":"2026-04-14","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://help.sorare.com/hc/en-us/articles/35374770201373-JONUM-Regulation","content_hash":null,"independence_group":"sorare","access_method":"indexed_browser_snapshot","direct_http_status":403},{"id":"source:sorare-cards:ukgc","title":"Consumer information notice: Sorare.com prosecution","url":"https://www.gamblingcommission.gov.uk/news/article/consumer-information-notice-sorare-com-prosecution","publisher":"UK Gambling Commission","published_at":"2024-09-26","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://www.gamblingcommission.gov.uk/news/article/consumer-information-notice-sorare-com-prosecution","content_hash":null,"independence_group":"uk_gambling_commission","access_method":"direct_http","direct_http_status":200},{"id":"source:sorare-cards:financial","title":"Sorare getting very close to the red","url":"https://sbcnews.co.uk/featurednews/2025/06/13/sorare-close-to-the-red/","publisher":"SBC News","published_at":"2025-06-13","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://sbcnews.co.uk/featurednews/2025/06/13/sorare-close-to-the-red/","content_hash":null,"independence_group":"sbc_news","access_method":"indexed_browser_snapshot","direct_http_status":403}],"claims":[{"id":"claim:sorare-cards:status","field_path":"status.operating_state","assertion":"Sorare remains operational in 2026 with card ownership on Solana, ETH settlement on Base and jurisdiction-specific competition rules.","value":"operating_after_chain_migration_with_financial_and_regulatory_pressure","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms","source:sorare-cards:ownership","source:sorare-cards:migration","source:sorare-cards:jonum"],"evidence_locator":"Current terms, wallet architecture, migration record and competition rules.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:outcome","field_path":"outcome.label","assertion":"Sorare achieved durable licensed fantasy gameplay but entered a retrenchment phase as reported revenue and cash reserves fell and legal treatment remained contested.","value":"surviving_product_with_repeat_gameplay_but_shrinking_economics_and_regulatory_risk","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sorare-cards:migration","source:sorare-cards:jonum","source:sorare-cards:ukgc","source:sorare-cards:financial"],"evidence_locator":"Operating migration and rules compared with regulator and independent financial reporting.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or a claim of holder profitability.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Sorare uses licensed digital player cards in fantasy competitions tied to real-world sports results.","value":"Sorare uses licensed digital player cards in fantasy competitions tied to real-world sports results.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms","source:sorare-cards:jonum"],"evidence_locator":"Service and competition descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Current Sorare wallets hold collectibles on Solana and ETH on Base.","value":"Current Sorare wallets hold collectibles on Solana and ETH on Base.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms","source:sorare-cards:ownership","source:sorare-cards:migration"],"evidence_locator":"Wallet and migration descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"The reviewed terms provide no equity or guaranteed appreciation right to card owners.","value":"The reviewed terms provide no equity or guaranteed appreciation right to card owners.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:sorare-cards:terms"],"evidence_locator":"Ownership and risk terms.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Independent reporting said Sorare revenue fell from €143 million in 2022 to €43 million in 2024.","value":"Independent reporting said Sorare revenue fell from €143 million in 2022 to €43 million in 2024.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:financial"],"evidence_locator":"Account figures summarized in the independent report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"Sorare completed a collectible migration from StarkEx to Solana with ETH settlement on Base.","value":"Sorare completed a collectible migration from StarkEx to Solana with ETH settlement on Base.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:migration","source:sorare-cards:ownership","source:sorare-cards:terms"],"evidence_locator":"Migration timeline and current wallet architecture.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"Sorare operates jurisdiction-specific JONUM competition rules in France.","value":"Sorare operates jurisdiction-specific JONUM competition rules in France.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:jonum"],"evidence_locator":"Current regulatory-competition notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body#1","assertion":"Recurring fantasy competitions give cards a use beyond passive collection.","value":"Recurring fantasy competitions give cards a use beyond passive collection.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sorare-cards:terms","source:sorare-cards:jonum"],"evidence_locator":"Competition mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body#2","assertion":"Seasonal card issuance and reward obligations create continuing product and economic requirements.","value":"Seasonal card issuance and reward obligations create continuing product and economic requirements.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sorare-cards:terms","source:sorare-cards:financial"],"evidence_locator":"Card-service terms and reported financial contraction.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"Lower revenue and continued operations support a retrenchment call rather than a dead-or-thriving binary.","value":"Lower revenue and continued operations support a retrenchment call rather than a dead-or-thriving binary.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sorare-cards:financial","source:sorare-cards:migration","source:sorare-cards:jonum"],"evidence_locator":"Financial trend compared with current operating evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"Sorare’s product is built around licensed sports identity and repeated competitions.","value":"Sorare’s product is built around licensed sports identity and repeated competitions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms","source:sorare-cards:jonum"],"evidence_locator":"Current service descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"Sorare replaced the older StarkEx card stack with Solana and Base infrastructure.","value":"Sorare replaced the older StarkEx card stack with Solana and Base infrastructure.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:migration","source:sorare-cards:ownership"],"evidence_locator":"Migration and current custody descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"Sorare uses jurisdiction-specific product rules instead of one universal competition format.","value":"Sorare uses jurisdiction-specific product rules instead of one universal competition format.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms","source:sorare-cards:jonum","source:sorare-cards:ukgc"],"evidence_locator":"Terms, French JONUM notice and UK enforcement record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"Sorare operates the competition, scoring, reward and marketplace layers around user-owned cards.","value":"Sorare operates the competition, scoring, reward and marketplace layers around user-owned cards.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms","source:sorare-cards:jonum"],"evidence_locator":"Service operation and competition terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"Transfers and withdrawals can be restricted for fraud, sanctions or legal compliance.","value":"Transfers and withdrawals can be restricted for fraud, sanctions or legal compliance.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms"],"evidence_locator":"Wallet and compliance clauses.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"Blockchain custody does not independently preserve Sorare competition eligibility or reward delivery.","value":"Blockchain custody does not independently preserve Sorare competition eligibility or reward delivery.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sorare-cards:terms","source:sorare-cards:ownership"],"evidence_locator":"Ownership boundary compared with operator-controlled game functions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"Primary card inventory and marketplace activity are disclosed components of Sorare’s service.","value":"Primary card inventory and marketplace activity are disclosed components of Sorare’s service.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms"],"evidence_locator":"Service and transaction provisions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"Card ownership does not create a disclosed claim on Sorare profit.","value":"Card ownership does not create a disclosed claim on Sorare profit.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:sorare-cards:terms"],"evidence_locator":"Ownership and transaction terms.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"Current take rate, licensing cost, reward expense and paying-user cohorts remain unpublished in the reviewed sources.","value":"Current take rate, licensing cost, reward expense and paying-user cohorts remain unpublished in the reviewed sources.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:sorare-cards:financial","source:sorare-cards:terms"],"evidence_locator":"Independent accounts summary and current terms.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"The actual product uses transferable scarce cards, rewards and a migrated chain stack.","value":"The actual product uses transferable scarce cards, rewards and a migrated chain stack.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms","source:sorare-cards:migration","source:sorare-cards:jonum"],"evidence_locator":"Current design and migration record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"Legal treatment differs by jurisdiction and product configuration.","value":"Legal treatment differs by jurisdiction and product configuration.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:jonum","source:sorare-cards:ukgc","source:sorare-cards:terms"],"evidence_locator":"French rules, UK prosecution notice and current terms.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"The user and profit effects of lower issuance or non-transferable cards are not established.","value":"The user and profit effects of lower issuance or non-transferable cards are not established.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:sorare-cards:financial","source:sorare-cards:terms"],"evidence_locator":"No controlled comparison in the reviewed record.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"Independent reporting described substantial revenue and cash-reserve contraction through 2024.","value":"Independent reporting described substantial revenue and cash-reserve contraction through 2024.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:financial"],"evidence_locator":"Reported company-account figures.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"The UK regulator published a prosecution notice concerning unlicensed gambling facilities.","value":"The UK regulator published a prosecution notice concerning unlicensed gambling facilities.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:ukgc"],"evidence_locator":"Consumer information notice.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"The reviewed notice does not establish a final conviction or a worldwide legal classification.","value":"The reviewed notice does not establish a final conviction or a worldwide legal classification.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:sorare-cards:ukgc"],"evidence_locator":"Procedural scope of the regulator notice.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"Sorare’s reported revenue contracted sharply after 2022.","value":"Sorare’s reported revenue contracted sharply after 2022.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:financial"],"evidence_locator":"Independent financial history.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"The platform remained operational through a major 2025–2026 custody and settlement migration.","value":"The platform remained operational through a major 2025–2026 custody and settlement migration.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:migration","source:sorare-cards:ownership","source:sorare-cards:terms"],"evidence_locator":"Migration and current-service record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Current operating continuity and economic contraction coexist.","value":"Current operating continuity and economic contraction coexist.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sorare-cards:financial","source:sorare-cards:migration","source:sorare-cards:jonum"],"evidence_locator":"Cross-source lifecycle synthesis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"Current evidence supports continued operation with lower historical revenue and active regulatory adaptation.","value":"Current evidence supports continued operation with lower historical revenue and active regulatory adaptation.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:financial","source:sorare-cards:migration","source:sorare-cards:jonum"],"evidence_locator":"Operating and financial record.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"Licensing, rewards, custody and legal availability are material ongoing dependencies.","value":"Licensing, rewards, custody and legal availability are material ongoing dependencies.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:sorare-cards:terms","source:sorare-cards:ownership","source:sorare-cards:ukgc"],"evidence_locator":"Current service and enforcement boundaries.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Current audited profitability and retained-manager cohorts remain unavailable.","value":"Current audited profitability and retained-manager cohorts remain unavailable.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:sorare-cards:financial","source:sorare-cards:terms"],"evidence_locator":"Reviewed public evidence.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:event:launch","field_path":"events[event:sorare-cards:launch]","assertion":"Sorare launched its football fantasy-card beta in March 2019.","value":"2019-03-01","as_of":"2019-03-01","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:history"],"evidence_locator":"Operator beta-rollout history.","support_direction":"supports","note":"Source precision: month.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:event:revenue-peak","field_path":"events[event:sorare-cards:revenue-peak]","assertion":"Independent reporting identified €143 million of 2022 revenue before a two-year contraction.","value":"2022-12-31","as_of":"2022-12-31","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:financial"],"evidence_locator":"Reported company-account comparison.","support_direction":"supports","note":"Source precision: year.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:sorare-cards:event:current-terms","field_path":"events[event:sorare-cards:current-terms]","assertion":"Current terms documented the post-migration Solana and Base wallet structure.","value":"2026-05-07","as_of":"2026-05-07","confidence":"high","kind":"fact","source_ids":["source:sorare-cards:terms","source:sorare-cards:ownership"],"evidence_locator":"Effective date and wallet provisions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:03:00Z","next_review_at":"2026-08-10T22:03:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["audited_2025_2026_financials","cash_runway","paying_manager_retention","primary_sales","marketplace_take_rate","licensing_costs","reward_expense","migration_attrition","older_card_liquidity"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"Sorare the company, its fantasy games, individual seasonal card NFTs, user wallets, league licensors and reward providers are separate.","metric_boundary":"Company revenue, primary card sales, secondary volume, card prices, active managers and competition entries measure different outcomes.","editorial_guardrail":"Do not call continuing competitions proof of healthy economics, and do not turn a prosecution notice into a conviction or universal gambling ruling.","explicit_unknowns":["audited_2025_2026_financials","cash_runway","paying_manager_retention","primary_sales","marketplace_take_rate","licensing_costs","reward_expense","migration_attrition","older_card_liquidity"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, related-token economics and market price are kept separate.","The operating call is separated from card investment performance and company profitability."]}}');

INSERT INTO _nft_ordinals_depth_wave_c_0100 (slug, canonical_profile) VALUES ('metroverse', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:metroverse","type":"nft_collection","slug":"metroverse","name":"Metroverse","aliases":[]},"classification":{"subtype":"ceased NFT strategy game","tags":["ethereum","gamefi","virtual_land","onchain_puzzle","open_source_wind_down","ceased"],"chains":["Ethereum"],"jurisdictions":[]},"status":{"operating_state":"game_and_operator_development_ceased_2023","as_of":"2026-08-03","claim_ids":["claim:metroverse:status"]},"outcome":{"label":"failed_game_economy_with_orderly_code_and_asset_release","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:metroverse:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Metroverse was an Ethereum strategy game centered on 10,000 city-block NFTs. Owners arranged blocks into neighborhoods, combined traits for score boosts and later competed through additional game modes and Metro Battles. The NFTs were both game inputs and transferable collectibles, but they did not represent ownership of the developer or a contractual share of game revenue. This report distinguishes the original operator-run game from the Ethereum contracts and community rights that survived its closure.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:what_it_is:1","claim:metroverse:section:what_it_is:2","claim:metroverse:section:what_it_is:3"]},"what_happened":{"body":"The Genesis collection launched in January 2022, followed by an optimization game and a roadmap of additional blocks, passes, characters and battle features. The team says it kept building during an eight-month engagement decline and released the final Metro Battles phase. In February 2023 it announced shutdown; by March 10 the Discord was closed, the last rewards were distributed, contracts and block data were released and creator royalties were set to zero. The NFTs remained, but operator-led play and development ended.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:what_happened:1","claim:metroverse:section:what_happened:2","claim:metroverse:section:what_happened:3"]},"why_this_outcome":{"body":"Metroverse sold a speculative land-and-optimization thesis into the 2021–2022 NFT-game cycle, but keeping value required people to return and play. The team reported that early optimization attracted attention, while the later battle loop did not restore engagement after the market turned. Building the roadmap was therefore not enough: completed features existed without a retained audience large enough to fund support. The 96 percent traffic decline is operator-reported and corroborated by contemporaneous coverage; revenue, retention and treasury data remain unavailable.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:why_this_outcome:1","claim:metroverse:section:why_this_outcome:2","claim:metroverse:section:why_this_outcome:3"]},"strategic_choices":{"body":"The team chose scarce city-block ownership, neighborhood-combination mechanics and a staged roadmap that culminated in competitive Battles. That created a reason to assemble multiple NFTs but made the game sensitive to collection prices, player liquidity and repeated strategic interest. During wind-down, the team chose completion and release over indefinite promises: it delivered final rewards, removed royalties and opened code and block data. Those actions reduced continuing dependence, but they occurred only after the operating audience had already collapsed.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:strategic_choices:1","claim:metroverse:section:strategic_choices:2","claim:metroverse:section:strategic_choices:3"]},"operating_model":{"body":"Players bought or traded Ethereum NFTs and connected them to a web game that calculated neighborhood scores and supported later competition. The operator maintained the interface, game rules, community and feature roadmap; token contracts preserved ownership separately. Continued operations depended on enough users to justify servers, moderation and development, and creator royalties were one possible revenue path. At closure, royalties became zero and operational responsibility did not automatically transfer to a named successor, leaving community reuse possible but unfunded.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:operating_model:1","claim:metroverse:section:operating_model:2","claim:metroverse:section:operating_model:3"]},"token_and_value_capture":{"body":"Primary NFT sales and any creator royalties could fund the project; holders could seek game utility or resale value. The design offered no disclosed fungible token dividend or automatic claim on revenue. When the team set royalties to zero and stopped the game, the main operator value loop ended. Surviving contracts could still be transferred or reused, but transfer activity is not project revenue and a secondary sale does not prove an active game. Final primary proceeds, royalty income, operating costs and holder losses are unknown.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:token_and_value_capture:1","claim:metroverse:section:token_and_value_capture:2","claim:metroverse:section:token_and_value_capture:3"]},"counterfactual":{"body":"The team could have tested retention before expanding asset types, limited the roadmap to the early optimization loop or designed a subscription-like revenue stream less dependent on NFT enthusiasm. A community-governed handoff might also have preserved a smaller game. None is proven to have worked: the team says the broader market decline preceded Battles, and no cohort or cost data shows which feature lost users. The strongest evidence-based lesson is to validate repeat play before scaling inventory and roadmap complexity.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:counterfactual:1","claim:metroverse:section:counterfactual:2","claim:metroverse:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The original game is closed, so remaining risks concern preservation and misrepresentation. A live contract or old website can be mistaken for an operating product; abandoned interfaces may break; community forks may lack authority or funding; and thin trades may be presented as recovery. The team was anonymous or not fully accountable in public materials, and a later legal study notes the project’s licensing limitations. Unknowns include final users, treasury, code maintenance, active forks, current holders, executable bids and whether archived metadata will remain available.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:risks_and_unknowns:1","claim:metroverse:section:risks_and_unknowns:2","claim:metroverse:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Metroverse had a short but complete product lifecycle: a January 2022 launch, a year of roadmap delivery, an engagement collapse, a February 2023 shutdown decision and completed wind-down by March 10. It is a useful failure case because the team did ship the promised final phase; delivery did not create sustainable retention. The project is dead as an operator-run game, while its contracts and assets are persistent artifacts. No verified community relaunch changes that classification as of August 3, 2026.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:lifecycle:1","claim:metroverse:section:lifecycle:2","claim:metroverse:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Metroverse remains an archived game with transferable NFTs and reusable code, not a recovering business. Watch whether the official archive and repository stay accessible, whether a named successor launches a playable product, whether that product retains users and whether any rights terms change. A few transfers or a community experiment would not by themselves revive the original operator. A recovery call requires current players, maintained software, responsible governance and an economic path that does not repeat the original engagement failure.","as_of":"2026-08-03","claim_ids":["claim:metroverse:section:outlook_and_watch:1","claim:metroverse:section:outlook_and_watch:2","claim:metroverse:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:metroverse:launch","type":"collection_launch","date":"2022-01-18","date_precision":"day","description":"Metroverse launched its Genesis city-block collection.","claim_ids":["claim:metroverse:event:launch"]},{"id":"event:metroverse:shutdown-announcement","type":"shutdown_announcement","date":"2023-02-24","date_precision":"day","description":"Metroverse announced that development and the game would end.","claim_ids":["claim:metroverse:event:shutdown-announcement"]},{"id":"event:metroverse:wind-down-complete","type":"service_shutdown","date":"2023-03-10","date_precision":"day","description":"Metroverse completed its stated Discord, reward, code-release and royalty wind-down steps.","claim_ids":["claim:metroverse:event:wind-down-complete"]}],"sources":[{"id":"source:metroverse:home","title":"Metroverse Genesis collection overview","url":"https://metroverse.com/","publisher":"Metroverse","published_at":"2022-01-18","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://metroverse.com/","content_hash":null,"independence_group":"metroverse","access_method":"direct_http","direct_http_status":200},{"id":"source:metroverse:roadmap","title":"Metroverse dated roadmap","url":"https://metroverse.com/roadmap","publisher":"Metroverse","published_at":"2022-01-18","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://metroverse.com/roadmap","content_hash":null,"independence_group":"metroverse","access_method":"direct_http","direct_http_status":200},{"id":"source:metroverse:closure","title":"Metroverse community closure notice","url":"https://metroverse.com/community-notice","publisher":"Metroverse","published_at":"2023-03-10","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://metroverse.com/community-notice","content_hash":null,"independence_group":"metroverse","access_method":"direct_http","direct_http_status":200},{"id":"source:metroverse:independent","title":"NFT strategy game Metroverse is shutting down","url":"https://www.coinlive.com/news-flash/13945","publisher":"Coinlive","published_at":"2023-02-24","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"C","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://www.coinlive.com/news-flash/13945","content_hash":null,"independence_group":"coinlive","access_method":"direct_http","direct_http_status":200},{"id":"source:metroverse:legal-study","title":"Decentralized Collaboration","url":"https://aulawreview.org/wp-content/uploads/2024/01/Lee.to_.Printer.pdf","publisher":"American University Law Review","published_at":"2024-01-01","published_at_precision":"month","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://aulawreview.org/wp-content/uploads/2024/01/Lee.to_.Printer.pdf","content_hash":null,"independence_group":"american_university_law_review","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:metroverse:status","field_path":"status.operating_state","assertion":"Metroverse ended game operations and development by March 10, 2023 after reporting a roughly 96 percent year-over-year fall in site visits.","value":"game_and_operator_development_ceased_2023","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:metroverse:closure","source:metroverse:independent"],"evidence_locator":"Operator closure notice and contemporaneous independent report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:outcome","field_path":"outcome.label","assertion":"Metroverse failed to retain enough game engagement to support operations, while its orderly shutdown preserved NFT ownership, code and reusable data.","value":"failed_game_economy_with_orderly_code_and_asset_release","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:metroverse:roadmap","source:metroverse:closure","source:metroverse:independent","source:metroverse:legal-study"],"evidence_locator":"Product roadmap, operator-reported decline, shutdown actions and later legal research.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or a claim of holder profitability.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"Metroverse launched a 10,000-piece Genesis city-block NFT collection on Ethereum.","value":"Metroverse launched a 10,000-piece Genesis city-block NFT collection on Ethereum.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:metroverse:home","source:metroverse:roadmap"],"evidence_locator":"Genesis overview and launch roadmap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"City blocks were used in neighborhood optimization and later competition modes.","value":"City blocks we