ection":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"The operator completed the final roadmap phase before ending support.","value":"The operator completed the final roadmap phase before ending support.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:metroverse:closure"],"evidence_locator":"Product retrospective and final checklist.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"No verified successor operation was identified in the reviewed current record.","value":"No verified successor operation was identified in the reviewed current record.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:metroverse:home","source:metroverse:closure","source:metroverse:independent"],"evidence_locator":"Current archive and terminal sources.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"The shutdown preserved reuse rights, contracts, code and block data.","value":"The shutdown preserved reuse rights, contracts, code and block data.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:metroverse:closure","source:metroverse:legal-study"],"evidence_locator":"Future and wind-down actions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"No current operator-led game is documented.","value":"No current operator-led game is documented.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:metroverse:closure","source:metroverse:independent"],"evidence_locator":"Terminal evidence remains controlling.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"A recovery would require new evidence of maintained play, governance and funding.","value":"A recovery would require new evidence of maintained play, governance and funding.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:metroverse:closure"],"evidence_locator":"Analyst threshold based on the documented failure mode.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:event:launch","field_path":"events[event:metroverse:launch]","assertion":"Metroverse launched its Genesis city-block collection.","value":"2022-01-18","as_of":"2022-01-18","confidence":"high","kind":"fact","source_ids":["source:metroverse:home","source:metroverse:roadmap"],"evidence_locator":"Dated collection roadmap.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:event:shutdown-announcement","field_path":"events[event:metroverse:shutdown-announcement]","assertion":"Metroverse announced that development and the game would end.","value":"2023-02-24","as_of":"2023-02-24","confidence":"high","kind":"fact","source_ids":["source:metroverse:closure","source:metroverse:independent"],"evidence_locator":"Operator notice and contemporaneous report.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:metroverse:event:wind-down-complete","field_path":"events[event:metroverse:wind-down-complete]","assertion":"Metroverse completed its stated Discord, reward, code-release and royalty wind-down steps.","value":"2023-03-10","as_of":"2023-03-10","confidence":"high","kind":"fact","source_ids":["source:metroverse:closure"],"evidence_locator":"Dated update to shutdown checklist.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:03:00Z","next_review_at":"2026-08-10T22:03:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["final_active_users","retention_cohorts","revenue_and_costs","treasury_runway","current_code_maintenance","community_forks","current_holder_count","executable_market_depth"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"The ceased Metroverse game, original development team, Ethereum NFT contracts, open-source code and any later community fork are separate.","metric_boundary":"Site visits, active game users, NFT transfers, floor prices and operator revenue measure different layers and are not interchangeable.","editorial_guardrail":"Do not call Metroverse a rug pull without stronger evidence, and do not call persistent contracts a live game.","explicit_unknowns":["final_active_users","retention_cohorts","revenue_and_costs","treasury_runway","current_code_maintenance","community_forks","current_holder_count","executable_market_depth"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, related-token economics and market price are kept separate.","The causal explanation uses the operator’s quantified decline but does not accept undisclosed blame claims as independently proven."]}}');

INSERT INTO _nft_ordinals_depth_wave_c_0100 (slug, canonical_profile) VALUES ('nouns-dao', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"nft_collection:nouns-dao","type":"nft_collection","slug":"nouns-dao","name":"Nouns","aliases":[]},"classification":{"subtype":"perpetual-auction governance NFT protocol","tags":["ethereum","cc0","daily_auction","dao","treasury","fork_exit","open_ended_supply"],"chains":["Ethereum"],"jurisdictions":[]},"status":{"operating_state":"operating_with_daily_issuance_and_holder_governance","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:status"]},"outcome":{"label":"durable_operating_protocol_with_governance_fragmentation_and_unproven_spending_efficiency","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:nouns-dao:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Nouns is an Ethereum protocol that creates one pixel-art governance NFT every 24 hours and sells it by auction. Each Noun carries one vote in Nouns DAO, and auction proceeds enter a treasury that holders govern through proposals. The artwork is released under CC0 for broad reuse. Unlike a fixed 10,000-item profile-picture collection, supply has no planned endpoint. A Noun is a membership and voting asset, not a contractual pro-rata share of treasury cash or guaranteed investment return.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:what_it_is:1","claim:nouns-dao:section:what_it_is:2","claim:nouns-dao:section:what_it_is:3"]},"what_happened":{"body":"Nouns launched in August 2021 with perpetual daily auctions and treasury-funded experiments. The model accumulated a large pool and funded media, public goods, events and community projects. In September 2023, after governance adopted a fork exit, more than half of eligible Nouns joined a split that moved roughly $27 million of assets according to contemporary reporting. The original DAO continued operating afterward. Current sites still show auctions, governance and treasury activity, so the fork was a major contraction and governance stress test rather than the protocol’s death.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:what_happened:1","claim:nouns-dao:section:what_happened:2","claim:nouns-dao:section:what_happened:3"]},"why_this_outcome":{"body":"Nouns survives because its core loop funds itself: each new member pays through an auction, and the proceeds finance work that can expand the brand. CC0 lets outsiders build without negotiating a license, while one-Noun-one-vote gives owners direct control. The same treasury creates an arbitrage problem when treasury value per Noun exceeds market price. The 2023 fork showed that some buyers valued an exit more than continued collective spending. Durable contracts therefore solved continuity, not agreement about capital allocation.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:why_this_outcome:1","claim:nouns-dao:section:why_this_outcome:2","claim:nouns-dao:section:why_this_outcome:3"]},"strategic_choices":{"body":"The founders chose perpetual issuance instead of a fixed supply, one-Noun-one-vote instead of a separate governance token and CC0 instead of restrictive licensing. They also directed every auction’s proceeds into a collectively governed treasury and later added a fork mechanism for dissatisfied holders. These choices create continuous membership, financing and remix culture. They also produce ongoing dilution, wealth-weighted voting, pressure to justify treasury spending and an exit path that can fragment the organization when asset-value buyers outnumber long-horizon builders.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:strategic_choices:1","claim:nouns-dao:section:strategic_choices:2","claim:nouns-dao:section:strategic_choices:3"]},"operating_model":{"body":"Anyone can settle an ended auction, which transfers the winning ETH into the treasury and starts the next auction. Noun holders or delegates submit and vote on proposals; approved transactions direct treasury assets. Builders can use CC0 art without obtaining a commercial license, while funded teams may receive grants through governance. There is no conventional executive promising a product roadmap. In practice, frontends, delegates, proposal authors and service providers remain important even when issuance and treasury execution are onchain.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:operating_model:1","claim:nouns-dao:section:operating_model:2","claim:nouns-dao:section:operating_model:3"]},"token_and_value_capture":{"body":"Primary auction ETH flows to Nouns DAO, not automatically to existing holders. Holders capture governance influence, cultural membership and any resale value; builders can capture grants for approved work. Open-ended supply means a buyer must weigh future issuance against treasury and brand growth. The fork mechanism can return a proportional pool to participants only under specific governance conditions; it is not an everyday redemption guarantee. Current net treasury performance, proposal return on spending, voter concentration and holder profit are not established.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:token_and_value_capture:1","claim:nouns-dao:section:token_and_value_capture:2","claim:nouns-dao:section:token_and_value_capture:3"]},"counterfactual":{"body":"A fixed-supply mint could have reduced dilution and treasury-value arbitrage, but it would remove the recurring membership and funding loop. A non-redeemable treasury might protect long-term grants while trapping dissenting owners; automatic pro-rata redemption could discipline spending while turning Nouns into a liquidation trade. More delegated committees could improve expertise but weaken direct ownership control. The 2023 fork supplies evidence about exit demand, not a controlled answer about which governance design would create better public goods.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:counterfactual:1","claim:nouns-dao:section:counterfactual:2","claim:nouns-dao:section:counterfactual:3"]},"risks_and_unknowns":{"body":"The main risks are auction-demand decline, voter and delegate concentration, treasury capture, low-quality grants, recurring forks, smart-contract or frontend failures and confusion between treasury assets and holder rights. CC0 encourages distribution but cannot force builders to return value to the DAO. A large treasury can keep governance active even if outside demand weakens. Unknowns include retained unique bidders, buyer-to-voter conversion, delegate concentration, proposal completion, measurable grant outcomes, treasury-adjusted dilution and the quality of current secondary liquidity.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:risks_and_unknowns:1","claim:nouns-dao:section:risks_and_unknowns:2","claim:nouns-dao:section:risks_and_unknowns:3"]},"lifecycle":{"body":"Nouns has operated from August 2021 through August 2026 with a distinctive recurring-auction model. It grew a major treasury and a recognizable open brand, then suffered a severe 2023 fork driven partly by treasury-value arbitrage and disagreement over spending. Daily issuance and governance survived, which is stronger evidence than a live marketing page alone. The lifecycle call is durable but mixed: the protocol works and funds activity, while the fork prevents a simple “thriving” label without better evidence on demand and spending quality.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:lifecycle:1","claim:nouns-dao:section:lifecycle:2","claim:nouns-dao:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: Nouns keeps auctioning new members and funding projects, but governance remains vulnerable when treasury backing, auction prices and holder objectives diverge. Watch unique auction bidders, clearing prices, voter participation, delegate concentration, treasury net of commitments, completed proposals, measurable audience growth and new fork participation. The call improves if repeat demand and verified project outcomes rise without another large exit. It worsens if auctions thin, treasury spending lacks delivery or arbitrage-driven forks repeatedly shrink the organization.","as_of":"2026-08-03","claim_ids":["claim:nouns-dao:section:outlook_and_watch:1","claim:nouns-dao:section:outlook_and_watch:2","claim:nouns-dao:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:nouns-dao:launch","type":"protocol_launch","date":"2021-08-08","date_precision":"day","description":"Nouns began its perpetual daily-auction protocol in August 2021.","claim_ids":["claim:nouns-dao:event:launch"]},{"id":"event:nouns-dao:fork","type":"governance_fork","date":"2023-09-15","date_precision":"day","description":"A majority-scale Nouns fork split membership and a material treasury share.","claim_ids":["claim:nouns-dao:event:fork"]},{"id":"event:nouns-dao:current-operation","type":"operating_observation","date":"2026-08-03","date_precision":"day","description":"Current official surfaces continued to expose auctions, governance and treasury activity.","claim_ids":["claim:nouns-dao:event:current-operation"]}],"sources":[{"id":"source:nouns-dao:contract","title":"Nouns token contract","url":"https://etherscan.io/address/0x9c8ff314c9bc7f6e59a9d9225fb22946427edc03","publisher":"Etherscan","published_at":"2021-08-08","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"aggregator","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://etherscan.io/address/0x9c8ff314c9bc7f6e59a9d9225fb22946427edc03","content_hash":null,"independence_group":"etherscan","access_method":"indexed_browser_snapshot","direct_http_status":403},{"id":"source:nouns-dao:protocol","title":"Nouns daily auction and governance protocol","url":"https://nouns.wtf/","publisher":"Nouns DAO","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://nouns.wtf/","content_hash":null,"independence_group":"nouns_dao","access_method":"direct_http","direct_http_status":200},{"id":"source:nouns-dao:world","title":"Welcome to Nouns","url":"https://www.nouns.world/","publisher":"Nouns DAO","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://www.nouns.world/","content_hash":null,"independence_group":"nouns_dao","access_method":"direct_http","direct_http_status":200},{"id":"source:nouns-dao:governance","title":"Nouns DAO governance proposals","url":"https://docs.nouns.wtf/governance/proposals","publisher":"Nouns DAO","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://docs.nouns.wtf/governance/proposals","content_hash":null,"independence_group":"nouns_dao","access_method":"direct_http","direct_http_status":200},{"id":"source:nouns-dao:stats","title":"Nouns treasury statistics","url":"https://www.nouns.com/stats/treasury","publisher":"Nouns.com","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"aggregator","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://www.nouns.com/stats/treasury","content_hash":null,"independence_group":"nouns_com","access_method":"direct_http","direct_http_status":200},{"id":"source:nouns-dao:fork-axios","title":"This NFT project break up is the crypto equivalent of Brexit","url":"https://www.axios.com/2023/09/15/the-nouns-a-top-tier-nft-project-is-breaking-up","publisher":"Axios","published_at":"2023-09-15","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://www.axios.com/2023/09/15/the-nouns-a-top-tier-nft-project-is-breaking-up","content_hash":null,"independence_group":"axios","access_method":"indexed_browser_snapshot","direct_http_status":403},{"id":"source:nouns-dao:fork-coindesk","title":"NounsDAO barrels toward treasury split","url":"https://www.coindesk.com/markets/2023/09/09/nounsdao-barrels-toward-treasury-split-after-nft-holders-rally-for-rage-quit","publisher":"CoinDesk","published_at":"2023-09-09","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://www.coindesk.com/markets/2023/09/09/nounsdao-barrels-toward-treasury-split-after-nft-holders-rally-for-rage-quit","content_hash":null,"independence_group":"coindesk","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:nouns-dao:status","field_path":"status.operating_state","assertion":"Nouns continues to mint and auction one governance NFT per day, sending proceeds to a treasury controlled by Noun owners.","value":"operating_with_daily_issuance_and_holder_governance","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:world","source:nouns-dao:governance","source:nouns-dao:stats"],"evidence_locator":"Current auction, governance and treasury surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:outcome","field_path":"outcome.label","assertion":"Nouns built a durable issuance-and-governance loop, but its 2023 treasury fork exposed a conflict between public-goods spending and holders seeking asset-value exits.","value":"durable_operating_protocol_with_governance_fragmentation_and_unproven_spending_efficiency","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:nouns-dao:protocol","source:nouns-dao:governance","source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk","source:nouns-dao:stats"],"evidence_locator":"Current mechanism and treasury data compared with independent fork reporting.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or a claim of holder profitability.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"The protocol creates and auctions one Noun every 24 hours.","value":"The protocol creates and auctions one Noun every 24 hours.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:world"],"evidence_locator":"Current auction-mechanism descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body#2","assertion":"Each Noun carries one delegatable vote and auction proceeds enter the DAO treasury.","value":"Each Noun carries one delegatable vote and auction proceeds enter the DAO treasury.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:governance"],"evidence_locator":"Governance and treasury descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:what_it_is:3","field_path":"analysis.sections.what_it_is.body#3","assertion":"Noun ownership does not create a simple contractual pro-rata treasury redemption right outside approved fork mechanics.","value":"Noun ownership does not create a simple contractual pro-rata treasury redemption right outside approved fork mechanics.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:nouns-dao:governance","source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Governance system and documented fork process.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:what_happened:1","field_path":"analysis.sections.what_happened.body#1","assertion":"Nouns began daily issuance in August 2021.","value":"Nouns began daily issuance in August 2021.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:contract","source:nouns-dao:protocol","source:nouns-dao:world"],"evidence_locator":"Contract deployment, protocol history and current mechanism.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:what_happened:2","field_path":"analysis.sections.what_happened.body#2","assertion":"A September 2023 fork attracted more than half of eligible Nouns and moved a large treasury share.","value":"A September 2023 fork attracted more than half of eligible Nouns and moved a large treasury share.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Contemporaneous independent fork reports.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:what_happened:3","field_path":"analysis.sections.what_happened.body#3","assertion":"The original Nouns auction and governance system remains active after the fork.","value":"The original Nouns auction and governance system remains active after the fork.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:world","source:nouns-dao:governance","source:nouns-dao:stats"],"evidence_locator":"Current official and treasury surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body#1","assertion":"Daily auctions provide recurring treasury funding without relying primarily on resale royalties.","value":"Daily auctions provide recurring treasury funding without relying primarily on resale royalties.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:nouns-dao:protocol","source:nouns-dao:world","source:nouns-dao:stats"],"evidence_locator":"Auction and treasury descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body#2","assertion":"CC0 reuse and holder voting broaden participation while keeping formal budget control with Noun owners.","value":"CC0 reuse and holder voting broaden participation while keeping formal budget control with Noun owners.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:nouns-dao:world","source:nouns-dao:governance"],"evidence_locator":"Brand and governance descriptions.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:why_this_outcome:3","field_path":"analysis.sections.why_this_outcome.body#3","assertion":"Independent reporting connected the 2023 fork to a gap between treasury backing and Noun market value.","value":"Independent reporting connected the 2023 fork to a gap between treasury backing and Noun market value.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Fork motive and mechanics in independent reports.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body#1","assertion":"Nouns uses open-ended daily issuance, NFT-based voting and a treasury funded by primary auctions.","value":"Nouns uses open-ended daily issuance, NFT-based voting and a treasury funded by primary auctions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:world","source:nouns-dao:governance"],"evidence_locator":"Current protocol design.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body#2","assertion":"Nouns artwork is offered under CC0 for permissionless reuse.","value":"Nouns artwork is offered under CC0 for permissionless reuse.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:world"],"evidence_locator":"Current brand description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:strategic_choices:3","field_path":"analysis.sections.strategic_choices.body#3","assertion":"The DAO adopted a fork mechanism that enabled a major 2023 treasury split.","value":"The DAO adopted a fork mechanism that enabled a major 2023 treasury split.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Independent history of the fork.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:operating_model:1","field_path":"analysis.sections.operating_model.body#1","assertion":"Auction settlement sends proceeds to the treasury and creates the next Noun.","value":"Auction settlement sends proceeds to the treasury and creates the next Noun.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol"],"evidence_locator":"Self-sufficient auction mechanism.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:operating_model:2","field_path":"analysis.sections.operating_model.body#2","assertion":"Noun owners and delegates vote on proposals that direct treasury spending.","value":"Noun owners and delegates vote on proposals that direct treasury spending.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:governance","source:nouns-dao:world"],"evidence_locator":"Governance workflow.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:operating_model:3","field_path":"analysis.sections.operating_model.body#3","assertion":"Onchain execution does not remove dependence on frontends, delegates, proposal authors and funded operators.","value":"Onchain execution does not remove dependence on frontends, delegates, proposal authors and funded operators.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:nouns-dao:protocol","source:nouns-dao:governance","source:nouns-dao:fork-axios"],"evidence_locator":"Protocol mechanics compared with observed governance conflict.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body#1","assertion":"One hundred percent of primary auction proceeds enter the Nouns treasury.","value":"One hundred percent of primary auction proceeds enter the Nouns treasury.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:world"],"evidence_locator":"Current auction economics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body#2","assertion":"Existing holders do not receive each auction’s proceeds as an automatic dividend.","value":"Existing holders do not receive each auction’s proceeds as an automatic dividend.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:nouns-dao:protocol","source:nouns-dao:governance"],"evidence_locator":"Treasury-control mechanism.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:token_and_value_capture:3","field_path":"analysis.sections.token_and_value_capture.body#3","assertion":"Current spending returns, voting concentration and realized holder outcomes are not disclosed as one reconciled dataset.","value":"Current spending returns, voting concentration and realized holder outcomes are not disclosed as one reconciled dataset.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:nouns-dao:stats","source:nouns-dao:governance"],"evidence_locator":"Current metrics and proposal surfaces.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body#1","assertion":"The actual protocol uses perpetual issuance and direct holder governance.","value":"The actual protocol uses perpetual issuance and direct holder governance.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:governance"],"evidence_locator":"Current mechanism.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body#2","assertion":"The 2023 fork provided an exit path and substantially reduced the original treasury.","value":"The 2023 fork provided an exit path and substantially reduced the original treasury.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Independent fork reports.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:counterfactual:3","field_path":"analysis.sections.counterfactual.body#3","assertion":"No controlled comparison establishes that fixed supply or a different redemption policy would improve governance.","value":"No controlled comparison establishes that fixed supply or a different redemption policy would improve governance.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk","source:nouns-dao:governance"],"evidence_locator":"Observed fork without experimental counterfactual.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:risks_and_unknowns:1","field_path":"analysis.sections.risks_and_unknowns.body#1","assertion":"The protocol depends on interested bidders to continue economically meaningful daily auctions.","value":"The protocol depends on interested bidders to continue economically meaningful daily auctions.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol"],"evidence_locator":"Auction continuation condition.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:risks_and_unknowns:2","field_path":"analysis.sections.risks_and_unknowns.body#2","assertion":"The 2023 fork demonstrates material governance and treasury-fragmentation risk.","value":"The 2023 fork demonstrates material governance and treasury-fragmentation risk.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Documented fork outcome.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:risks_and_unknowns:3","field_path":"analysis.sections.risks_and_unknowns.body#3","assertion":"Current bidder retention, voter concentration and proposal outcomes are not reconciled in the reviewed sources.","value":"Current bidder retention, voter concentration and proposal outcomes are not reconciled in the reviewed sources.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:nouns-dao:stats","source:nouns-dao:governance"],"evidence_locator":"Available current dashboards.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:lifecycle:1","field_path":"analysis.sections.lifecycle.body#1","assertion":"Nouns has maintained daily auctions and governance from 2021 into 2026.","value":"Nouns has maintained daily auctions and governance from 2021 into 2026.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:contract","source:nouns-dao:protocol","source:nouns-dao:world","source:nouns-dao:governance"],"evidence_locator":"Historical launch context and current operation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:lifecycle:2","field_path":"analysis.sections.lifecycle.body#2","assertion":"The 2023 fork removed a material share of membership and treasury assets.","value":"The 2023 fork removed a material share of membership and treasury assets.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Independent event reporting.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:lifecycle:3","field_path":"analysis.sections.lifecycle.body#3","assertion":"Operating continuity does not establish efficient spending or positive holder returns.","value":"Operating continuity does not establish efficient spending or positive holder returns.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:nouns-dao:stats","source:nouns-dao:governance","source:nouns-dao:fork-axios"],"evidence_locator":"Current activity and historical stress evidence.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:outlook_and_watch:1","field_path":"analysis.sections.outlook_and_watch.body#1","assertion":"The protocol remains capable of recurring auctions, proposals and treasury spending.","value":"The protocol remains capable of recurring auctions, proposals and treasury spending.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:governance","source:nouns-dao:stats"],"evidence_locator":"Current mechanism and dashboard.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:outlook_and_watch:2","field_path":"analysis.sections.outlook_and_watch.body#2","assertion":"The 2023 fork identifies treasury-value divergence as a concrete watch signal.","value":"The 2023 fork identifies treasury-value divergence as a concrete watch signal.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Independent explanation of exit demand.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:section:outlook_and_watch:3","field_path":"analysis.sections.outlook_and_watch.body#3","assertion":"Current retained-bidder and proposal-outcome cohorts remain unverified.","value":"Current retained-bidder and proposal-outcome cohorts remain unverified.","as_of":"2026-08-03","confidence":"medium","kind":"unknown","source_ids":["source:nouns-dao:stats","source:nouns-dao:governance"],"evidence_locator":"Reviewed current surfaces.","support_direction":"context_only","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:event:launch","field_path":"events[event:nouns-dao:launch]","assertion":"Nouns began its perpetual daily-auction protocol in August 2021.","value":"2021-08-08","as_of":"2021-08-08","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:contract","source:nouns-dao:protocol","source:nouns-dao:world"],"evidence_locator":"Contract deployment and operating description.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:event:fork","field_path":"events[event:nouns-dao:fork]","assertion":"A majority-scale Nouns fork split membership and a material treasury share.","value":"2023-09-15","as_of":"2023-09-15","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:fork-axios","source:nouns-dao:fork-coindesk"],"evidence_locator":"Contemporaneous independent reports.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:nouns-dao:event:current-operation","field_path":"events[event:nouns-dao:current-operation]","assertion":"Current official surfaces continued to expose auctions, governance and treasury activity.","value":"2026-08-03","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:nouns-dao:protocol","source:nouns-dao:world","source:nouns-dao:governance","source:nouns-dao:stats"],"evidence_locator":"Observed current product surfaces.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T22:03:00Z","next_review_at":"2026-08-10T22:03:00Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":["unique_bidder_retention","buyer_to_voter_conversion","delegate_concentration","proposal_completion","grant_outcomes","treasury_commitments","secondary_market_depth","holder_returns"]},"extensions":{"legacy_origin":"nft_collections","identity_boundary":"The Nouns NFT, Nouns DAO treasury, auction protocol, delegates, funded builders, forks and unrelated $NOUNS-branded assets are separate.","metric_boundary":"Auction revenue, treasury value, proposal spending, NFT price, bidder count and governance participation measure different outcomes.","editorial_guardrail":"Do not describe the treasury as automatically redeemable backing or use live auctions alone as proof of efficient governance.","explicit_unknowns":["unique_bidder_retention","buyer_to_voter_conversion","delegate_concentration","proposal_completion","grant_outcomes","treasury_commitments","secondary_market_depth","holder_returns"],"methodology_notes":["Source verification and evidence assembly are complete; every claim remains pending until a person reviews it.","Collection activity, operator health, holder rights, related-token economics and market price are kept separate.","Protocol continuity is separated from governance quality, treasury efficiency and holder investment performance."]}}');

INSERT INTO _nft_ordinals_depth_wave_c_0100 (slug, canonical_profile) VALUES ('twelvefold', '{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"ordinals_collection:twelvefold","type":"ordinals_collection","slug":"twelvefold","name":"TwelveFold","aliases":[]},"classification":{"subtype":"finite Bitcoin Ordinals generative-art collection","tags":["bitcoin","ordinals","generative_art","auction","yuga_labs","finite_program"],"chains":["Bitcoin"],"jurisdictions":["United States"]},"status":{"operating_state":"finite_artifact_persistent_recurring_program_and_current_market_unverified","as_of":"2026-08-03","claim_ids":["claim:twelvefold:status"]},"outcome":{"label":"successful_primary_art_auction_with_persistent_artifact_but_unclassified_current_market","as_of":"2026-08-03","rule_id":"nft-lifecycle-evidence-v1","confidence":"high","claim_ids":["claim:twelvefold:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"TwelveFold is a 300-piece generative-art collection created by Yuga Labs and inscribed on individual satoshis in 2023. The work uses a base-12 system and a 12-by-12 grid to connect time, mathematics and Bitcoin’s ordinal numbering. It is separate from Bored Ape Yacht Club and Yuga’s Ethereum ecosystem. Buyers acquired specific Bitcoin inscriptions and a limited license under sale terms; they did not buy Yuga equity, copyright ownership, recurring revenue or a guaranteed future program.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:what_it_is:1","claim:twelvefold:section:what_it_is:2","claim:twelvefold:section:what_it_is:3"]},"what_happened":{"body":"Yuga announced TwelveFold in February 2023 and auctioned 288 works in March, reserving 12 for contributors and philanthropic purposes. CoinDesk reported that the auction drew 3,246 bidders and generated about 735.7 BTC, then worth roughly $16.5 million; the top accepted bid approached $160,000. Yuga later ran a 13-part puzzle series with BTC prizes and offered physical pieces to holders, with claims closing in June 2024. No reviewed source documents a comparable recurring program after that finite sequence.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:what_happened:1","claim:twelvefold:section:what_happened:2","claim:twelvefold:section:what_happened:3"]},"why_this_outcome":{"body":"TwelveFold converted Yuga’s brand and the novelty of early Ordinals into unusually strong primary demand for a tiny supply. The Bitcoin-native design, distinctive art system and auction scarcity differentiated it from another large profile-picture mint. That explains the launch, not current liquidity. The collection’s follow-on puzzles and physicals were finite, and a 300-piece supply can produce rare high-value sales while still offering little executable depth. Magic Eden’s 2026 Bitcoin exit removed one major trading surface and makes fresh market evidence more important.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:why_this_outcome:1","claim:twelvefold:section:why_this_outcome:2","claim:twelvefold:section:why_this_outcome:3"]},"strategic_choices":{"body":"Yuga chose Bitcoin Ordinals instead of extending an existing Ethereum collection, a highly limited 300-piece supply instead of mass distribution and a sealed-bid auction instead of a fixed mint price. It kept 12 works for contributors, donations and philanthropy, then added puzzles and physical art without promising a permanent roadmap. These choices protected artistic separation and scarcity, generated powerful price discovery and limited dilution. They also reduced holder breadth and made current market quality difficult to observe.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:strategic_choices:1","claim:twelvefold:section:strategic_choices:2","claim:twelvefold:section:strategic_choices:3"]},"operating_model":{"body":"Yuga created the artwork, conducted the one-time BTC auction and delivered inscriptions to successful bidders. Holders self-custody Bitcoin inscriptions and may transfer them through compatible wallets or marketplaces. Yuga later operated time-bounded puzzles and physical claims, but no subscription, treasury, DAO or continuing service obligation appears in the reviewed terms. Bitcoin preserves the inscription record; websites and marketplaces provide discovery and trading. Those layers can disappear without deleting the artwork.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:operating_model:1","claim:twelvefold:section:operating_model:2","claim:twelvefold:section:operating_model:3"]},"token_and_value_capture":{"body":"Yuga captured the primary auction proceeds. Holders captured the artwork, the license stated in the terms, finite puzzle or physical opportunities when eligible and any resale proceeds they could obtain. There is no separate TwelveFold token, revenue share or automatic royalty stream for holders. Historical auction value is not current market capitalization, and a rare asking price is not executable liquidity. Current royalties, active holders, bids, sale frequency and Yuga’s net costs are not established by the reviewed record.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:token_and_value_capture:1","claim:twelvefold:section:token_and_value_capture:2","claim:twelvefold:section:token_and_value_capture:3"]},"counterfactual":{"body":"A larger fixed-price release could have broadened ownership but sacrificed scarcity and auction proceeds. Direct integration with Yuga’s Ethereum ecosystem might create more utility while weakening the Bitcoin-native thesis. A recurring exhibition or puzzle schedule could show continuing stewardship but would turn a finite art experiment into an operating product. None is proven superior: the primary auction was exceptionally successful, and current evidence does not show whether added utility would improve long-term collector demand or merely add cost.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:counterfactual:1","claim:twelvefold:section:counterfactual:2","claim:twelvefold:section:counterfactual:3"]},"risks_and_unknowns":{"body":"Risks include thin-market pricing, Bitcoin wallet mistakes, marketplace dependence, licensing misunderstanding, phishing around rare inscriptions and confusing Yuga’s continuing corporate activity with TwelveFold-specific support. The 300-piece cap magnifies holder concentration and makes a single sale a weak trend measure. Magic Eden’s Bitcoin exit reduced one distribution channel. Unknowns include current beneficial holders, inscription movement, bids, unique buyers and sellers, royalties, private sales, physical delivery, creator staffing and whether Yuga plans another TwelveFold-specific program.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:risks_and_unknowns:1","claim:twelvefold:section:risks_and_unknowns:2","claim:twelvefold:section:risks_and_unknowns:3"]},"lifecycle":{"body":"TwelveFold moved from a February 2023 announcement to a high-demand March auction, then through inscriptions, puzzles and a 2024 physical-art claim. Its artifact layer remains intact and Yuga still identifies the collection, but the documented product sequence was finite. The lifecycle call therefore separates launch from present market: successful primary art release, persistent Bitcoin artifact and unclassified current collector economy. It is not dead simply because no new roadmap exists, and it is not thriving based on a three-year-old auction.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:lifecycle:1","claim:twelvefold:section:lifecycle:2","claim:twelvefold:section:lifecycle:3"]},"outlook_and_watch":{"body":"Base case: TwelveFold remains a recognized, scarce Bitcoin art collection with episodic private or marketplace trades, but market health stays unclassified. Watch verified transfers, unique buyers and sellers, executable bids, holder concentration, Yuga-specific updates, exhibitions and replacement Bitcoin venues after Magic Eden’s exit. The call improves if repeated arm’s-length sales and active stewardship appear. It worsens if official surfaces disappear or ownership becomes so concentrated that quoted prices have no reliable market behind them.","as_of":"2026-08-03","claim_ids":["claim:twelvefold:section:outlook_and_watch:1","claim:twelvefold:section:outlook_and_watch:2","claim:twelvefold:section:outlook_and_watch:3"]}}},"metrics":[],"events":[{"id":"event:twelvefold:announcement","type":"collection_announcement","date":"2023-02-27","date_precision":"day","description":"Yuga announced TwelveFold as a 300-piece Bitcoin generative-art collection.","claim_ids":["claim:twelvefold:event:announcement"]},{"id":"event:twelvefold:auction","type":"primary_auction","date":"2023-03-06","date_precision":"day","description":"The auction allocated 288 works and generated about 735.7 BTC according to CoinDesk.","claim_ids":["claim:twelvefold:event:auction"]},{"id":"event:twelvefold:physical-claims-close","type":"holder_program_end","date":"2024-06-14","date_precision":"day","description":"The official timeline records the end of the physical TwelveFold claim window.","claim_ids":["claim:twelvefold:event:physical-claims-close"]}],"sources":[{"id":"source:twelvefold:site","title":"TwelveFold collection archive and timeline","url":"https://twelvefold.io/","publisher":"Yuga Labs","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://twelvefold.io/","content_hash":null,"independence_group":"yuga_labs","access_method":"direct_http","direct_http_status":200},{"id":"source:twelvefold:terms","title":"TwelveFold terms of sale","url":"https://twelvefold.io/terms-of-sale.html","publisher":"Yuga Labs","published_at":"2023-03-04","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"A","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://twelvefold.io/terms-of-sale.html","content_hash":null,"independence_group":"yuga_labs","access_method":"direct_http","direct_http_status":200},{"id":"source:twelvefold:about","title":"Yuga Labs collections portfolio","url":"https://yuga.com/about/","publisher":"Yuga Labs","published_at":null,"published_at_precision":null,"accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://yuga.com/about/","content_hash":null,"independence_group":"yuga_labs","access_method":"direct_http","direct_http_status":200},{"id":"source:twelvefold:auction-report","title":"Yuga Labs'' Bitcoin NFT collection fetches top bid of nearly $160K","url":"https://www.coindesk.com/web3/2023/03/06/yugas-bitcoin-nft-collection-fetches-top-bid-of-nearly-160k","publisher":"CoinDesk","published_at":"2023-03-06","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://www.coindesk.com/web3/2023/03/06/yugas-bitcoin-nft-collection-fetches-top-bid-of-nearly-160k","content_hash":null,"independence_group":"coindesk","access_method":"direct_http","direct_http_status":200},{"id":"source:twelvefold:marketplace-exit","title":"Magic Eden marketplace updates and service changes","url":"https://help.magiceden.io/en/articles/13885504-magic-eden-marketplace-updates-service-changes","publisher":"Magic Eden","published_at":"2026-06-30","published_at_precision":"day","accessed_at":"2026-08-03T22:03:00Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T22:03:00Z","access_final_url":"https://help.magiceden.io/en/articles/13885504-magic-eden-marketplace-updates-service-changes","content_hash":null,"independence_group":"magic_eden","access_method":"direct_http","direct_http_status":200}],"claims":[{"id":"claim:twelvefold:status","field_path":"status.operating_state","assertion":"TwelveFold’s 300 Bitcoin inscriptions and Yuga archive remain identifiable, while no current recurring holder program or verified liquid market is established.","value":"finite_artifact_persistent_recurring_program_and_current_market_unverified","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:twelvefold:site","source:twelvefold:about","source:twelvefold:marketplace-exit"],"evidence_locator":"Current collection archive and Yuga portfolio listing, bounded by a 2026 Bitcoin marketplace closure.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:twelvefold:outcome","field_path":"outcome.label","assertion":"TwelveFold succeeded as a scarce primary art sale and finite creative experiment, but the reviewed evidence cannot classify current collector-market health.","value":"successful_primary_art_auction_with_persistent_artifact_but_unclassified_current_market","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:twelvefold:site","source:twelvefold:terms","source:twelvefold:auction-report","source:twelvefold:about","source:twelvefold:marketplace-exit"],"evidence_locator":"Launch, legal terms, independent auction result and current distribution evidence.","support_direction":"supports","note":"Lifecycle classification, not a price forecast or a claim of holder profitability.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:twelvefold:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body#1","assertion":"TwelveFold contains 300 generative artworks inscribed on satoshis on Bitcoin.","value":"TwelveFold contains 300 generative artworks inscribed on satoshis on Bitcoin.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:twelvefold:site","s